//! Typed accessors over the messages of `descriptor.proto` (spec 0424 S6).
//!
//! GENERATED by `tests/descriptor_access.rs` from `vendor/descriptor.pb`,
//! the `descriptor.proto` of the vendored upb (`vendor/VERSION`), whose
//! comments document each type and field below. Do not edit: run
//! `PROTOTEXT_UPB_REGENERATE=1 cargo test -p prototext-upb --test
//! descriptor_access -- --ignored`, as `scripts/update-upb` does.
//!
//! Each type wraps a [`MessageRef`] (and its `…Mut` twin a [`MessageMut`])
//! of that message type, from any package: the `descriptor.proto` of the
//! input or of a variant. Each accessor goes by field number in the
//! message's own type, so a field that version of `descriptor.proto` lacks
//! reads as its zero value, empty or `None`, and cannot be written. Strings
//! are bytes, as [`Value::Bytes`] has them; an enum is its number, with the
//! enum's values as constants in a module of its name.

use crate::{MessageError, MessageMut, MessageRef, Scalar, Value};

fn f64_(v: Option<Value<'_>>) -> f64 {
    match v {
        Some(Value::F64(x)) => x,
        _ => 0.0,
    }
}

fn i64_(v: Option<Value<'_>>) -> i64 {
    match v {
        Some(Value::I64(x)) => x,
        _ => 0,
    }
}

fn u64_(v: Option<Value<'_>>) -> u64 {
    match v {
        Some(Value::U64(x)) => x,
        _ => 0,
    }
}

fn i32_(v: Option<Value<'_>>) -> i32 {
    match v {
        Some(Value::I32(x)) => x,
        _ => 0,
    }
}

fn i32s(v: Option<Value<'_>>) -> Vec<i32> {
    match v {
        Some(Value::List(l)) => l.iter().map(|x| i32_(Some(x))).collect(),
        _ => Vec::new(),
    }
}

fn bool_(v: Option<Value<'_>>) -> bool {
    match v {
        Some(Value::Bool(x)) => x,
        _ => false,
    }
}

fn enum_(v: Option<Value<'_>>) -> i32 {
    match v {
        Some(Value::Enum(x)) => x,
        _ => 0,
    }
}

fn enums(v: Option<Value<'_>>) -> Vec<i32> {
    match v {
        Some(Value::List(l)) => l.iter().map(|x| enum_(Some(x))).collect(),
        _ => Vec::new(),
    }
}

fn bytes<'a>(v: Option<Value<'a>>) -> &'a [u8] {
    match v {
        Some(Value::Bytes(b)) => b,
        _ => &[],
    }
}

fn bytess<'a>(v: Option<Value<'a>>) -> Vec<&'a [u8]> {
    match v {
        Some(Value::List(l)) => l.iter().map(|x| bytes(Some(x))).collect(),
        _ => Vec::new(),
    }
}

fn message<'a>(v: Option<Value<'a>>) -> Option<MessageRef<'a>> {
    match v {
        Some(Value::Message(m)) => m,
        _ => None,
    }
}

fn messages<'a>(v: Option<Value<'a>>) -> Vec<MessageRef<'a>> {
    match v {
        Some(Value::List(l)) => l.iter().filter_map(|x| message(Some(x))).collect(),
        _ => Vec::new(),
    }
}

/// ```text
/// The protocol compiler can output a FileDescriptorSet containing the .proto
/// files it parses.
/// ```
#[derive(Debug, Clone)]
pub struct FileDescriptorSet<'a>(pub MessageRef<'a>);

impl<'a> FileDescriptorSet<'a> {
    /// `m` as a `FileDescriptorSet`, when its type is one, in any package.
    pub fn new(m: MessageRef<'a>) -> Option<Self> {
        (m.descriptor().name() == "FileDescriptorSet").then_some(Self(m))
    }

    pub fn file(&self) -> Vec<FileDescriptorProto<'a>> {
        messages(self.0.get_by_number(1))
            .into_iter()
            .map(FileDescriptorProto)
            .collect()
    }
}

